(function(){
'use strict';
const KEY='nawaf-hq-v5';
const APPS={
 mueen:{id:'mueen',name:'مُعِين',url:'https://mueen-islamic-app.vercel.app/',repo:'https://github.com/uauz1/mueen-islamic-app',desc:'التطبيق الإسلامي — الصلاة، القرآن، الأذكار، القصص والبث المباشر',accent:'#d8ae5d'},
 qaddha:{id:'qaddha',name:'قدّها',url:'https://qaddha.vercel.app/',repo:'https://github.com/uauz1/game',desc:'منصة الألعاب الجماعية — الألعاب، المحتوى، الجلسات والغرف',accent:'#6b8dff'}
};
const $=s=>document.querySelector(s);
function state(){try{return JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch{return {}}}
function save(s){localStorage.setItem(KEY,JSON.stringify(s))}
function esc(s=''){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function project(s,id){return (s.projects||[]).find(p=>p.id===id)||{id,name:APPS[id].name,status:'ACTIVE',phase:'جاهز للعمل',progress:0}}
function employeeName(s,id){return (s.employees||[]).find(e=>e.id===id)?.name||'غير مسند'}
function addActivity(s,text){s.activity=Array.isArray(s.activity)?s.activity:[];s.activity.unshift({id:'a'+Date.now().toString(36),text,type:'REAL',at:new Date().toISOString()});s.activity=s.activity.slice(0,100)}
function card(a,s){const p=project(s,a.id),tasks=(s.tasks||[]).filter(t=>t.projectId===a.id),reports=(s.reports||[]).filter(r=>r.projectId===a.id);return `<article class="connected-app" style="--app-accent:${a.accent}"><div class="connected-app-head"><div class="app-mark">${a.name.charAt(0)}</div><div><h3>${a.name}</h3><p>${a.desc}</p></div><span class="app-live">مرتبط</span></div><div class="connected-app-meta"><span>الحالة <b>${esc(p.status||'ACTIVE')}</b></span><span>المرحلة <b>${esc(p.phase||'جاهز للعمل')}</b></span><span>التقدم <b>${Number(p.progress)||0}%</b></span></div><div class="connected-app-meta"><span>المهام <b>${tasks.length}</b></span><span>المكتمل <b>${tasks.filter(t=>t.status==='COMPLETED').length}</b></span><span>التقارير <b>${reports.length}</b></span></div><div class="connected-app-actions"><a class="primary app-link" href="${a.url}" target="_blank" rel="noopener noreferrer">فتح ${a.name}</a><button type="button" data-dashboard="${a.id}">لوحة تحكم ${a.name}</button><a class="app-link" href="${a.repo}" target="_blank" rel="noopener noreferrer">GitHub</a><button type="button" data-report="${a.id}">تقرير سريع</button></div><div class="apps-output" id="panel-${a.id}" hidden></div></article>`}
function render(){const s=state();$('#apps-grid').innerHTML=Object.values(APPS).map(a=>card(a,s)).join('');$('#project-select').innerHTML=Object.values(APPS).map(a=>`<option value="${a.id}">${a.name}</option>`).join('');$('#employee-select').innerHTML=(s.employees||[]).map(e=>`<option value="${esc(e.id)}">${esc(e.name)} — ${esc(e.role||'')}</option>`).join('');renderHistory(s);bindCards()}
function renderHistory(s){const list=(s.tasks||[]).filter(t=>APPS[t.projectId]).slice(0,12);$('#apps-history').innerHTML=list.length?list.map(t=>`<div class="control-row"><div><b>${esc(t.title)}</b><small>${esc(APPS[t.projectId]?.name||t.projectId)} • ${esc(employeeName(s,t.employeeId))}</small></div><span>${esc(t.status||'READY')} • ${Number(t.progress)||0}%</span></div>`).join(''):'<p class="muted">لا توجد مهام بعد.</p>'}
function dashboard(id){const s=state(),a=APPS[id],p=project(s,id),tasks=(s.tasks||[]).filter(t=>t.projectId===id),reports=(s.reports||[]).filter(r=>r.projectId===id),box=$('#panel-'+id);box.hidden=false;box.innerHTML=`<b>لوحة تحكم ${a.name}</b><br>المرحلة: ${esc(p.phase||'جاهز للعمل')} • التقدم: ${Number(p.progress)||0}% • المهام: ${tasks.length} • التقارير: ${reports.length}<br><br>${tasks.slice(0,5).map(t=>`• ${esc(t.title)} — ${esc(t.status||'READY')} — ${Number(t.progress)||0}%`).join('<br>')||'لا توجد مهام حالية.'}`;addActivity(s,`فتح لوحة تحكم ${a.name}`);save(s)}
function report(id){const s=state(),a=APPS[id],p=project(s,id),tasks=(s.tasks||[]).filter(t=>t.projectId===id),box=$('#panel-'+id);box.hidden=false;box.innerHTML=`<b>تقرير ${a.name}</b><br>الحالة: ${esc(p.status||'ACTIVE')}<br>المرحلة: ${esc(p.phase||'جاهز للعمل')}<br>التقدم: ${Number(p.progress)||0}%<br>المهام: ${tasks.length}<br>المكتمل: ${tasks.filter(t=>t.status==='COMPLETED').length}<br>بانتظار نواف: ${tasks.filter(t=>t.status==='WAITING_FOR_NAWAF').length}`;addActivity(s,`إنشاء تقرير سريع عن ${a.name}`);save(s)}
function bindCards(){document.querySelectorAll('[data-dashboard]').forEach(b=>b.onclick=()=>dashboard(b.dataset.dashboard));document.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>report(b.dataset.report))}
$('#command-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget),s=state(),projectId=String(f.get('projectId')||''),employeeId=String(f.get('employeeId')||''),command=String(f.get('command')||'').trim(),status=String(f.get('status')||'READY');if(!command)return;s.tasks=Array.isArray(s.tasks)?s.tasks:[];const t={id:'t'+Date.now().toString(36),title:command.slice(0,90),details:command,projectId,employeeId,status,progress:0,createdAt:new Date().toISOString()};s.tasks.unshift(t);const emp=(s.employees||[]).find(x=>x.id===employeeId);if(emp){emp.task=t.title;emp.status=status}const p=(s.projects||[]).find(x=>x.id===projectId);if(p){p.phase='قيد التنفيذ';p.status='ACTIVE'}addActivity(s,`${employeeName(s,employeeId)} استلم مهمة على ${APPS[projectId]?.name||projectId}: ${t.title}`);save(s);$('#command-output').textContent=`تم إرسال المهمة إلى ${employeeName(s,employeeId)} على ${APPS[projectId]?.name||projectId}. ستظهر الآن داخل NAWAF HQ.`;e.currentTarget.reset();render()});
render();
})();